import { Stylesheet, Vec2 } from '@archeglyph/proto/gen/style_pb';

/**
 * Content assigned to an annotation before the user replaces it.
 *
 * An annotation's bounds are derived from its label, so an empty label would
 * make a newly-created annotation impossible to see or select.  This is
 * deliberately real content rather than a visual placeholder: it gives the
 * annotation a measurable label during creation and remains recoverable if
 * the user leaves it untouched.
 */
export const NEW_ANNOTATION_TEXT: string = 'New annotation';

/**
 * Temporary box used while a new annotation's label is being measured.
 * Layout derives the real size from the label; this is only the initial
 * space needed by the inline editor during the scene rebuild.
 */
export const NEW_ANNOTATION_SIZE: Vec2 = { x: 160, y: 40 };

export function newAnnotationId(stylesheet: Stylesheet, base: string): string {
  if (!Object.prototype.hasOwnProperty.call(stylesheet.annotations, base)) {
    return base;
  }

  let suffix = 2;
  while (Object.prototype.hasOwnProperty.call(stylesheet.annotations, `${base}-${suffix}`)) {
    suffix += 1;
  }

  return `${base}-${suffix}`;
}
